package com.biliwind.blog.service;

import com.biliwind.blog.context.RegionContext;
import com.biliwind.blog.model.BlogRegion;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.context.ContextNotActiveException;
import jakarta.inject.Inject;
import org.eclipse.microprofile.config.inject.ConfigProperty;

/**
 * Provides the public origin used for links generated by the application.
 * Inside a request the current region's domain rule wins, so the Chinese site
 * emits its own domain and the global site emits the international one.
 * Scheduled or background callers have no request region and fall back to the
 * deployment setting, so email and SEO links can never point at an empty host.
 */
@ApplicationScoped
public class PublicUrlService {

    @ConfigProperty(name = "windblog.site.public-url", defaultValue = "http://localhost:8080")
    String configuredPublicUrl;

    @Inject
    RegionContext regionContext;

    @Inject
    RegionRuleService regionRuleService;

    public String getBaseUrl() {
        String regionalUrl = regionalBaseUrl();
        return regionalUrl == null ? getConfiguredBaseUrl() : regionalUrl;
    }

    /** Deployment default that ignores the current region. */
    public String getConfiguredBaseUrl() {
        return normalize(configuredPublicUrl);
    }

    public String buildPath(String path) {
        String normalizedPath = path;
        if (normalizedPath == null || normalizedPath.isBlank()) {
            normalizedPath = "/";
        }
        if (!normalizedPath.startsWith("/")) {
            normalizedPath = "/" + normalizedPath;
        }
        return getBaseUrl() + normalizedPath;
    }

    private String regionalBaseUrl() {
        if (regionContext == null || regionRuleService == null) {
            return null;
        }
        BlogRegion region;
        try {
            region = regionContext.getCurrentRegion();
        } catch (ContextNotActiveException ignored) {
            return null;
        }
        if (region == null) {
            return null;
        }
        String url = regionRuleService.siteUrlFor(region);
        return url == null || url.isBlank() ? null : url;
    }

    public static String normalize(String value) {
        if (value == null || value.isBlank()) {
            return "http://localhost:8080";
        }
        String normalized = value.trim();
        while (normalized.endsWith("/") && normalized.length() > 1) {
            normalized = normalized.substring(0, normalized.length() - 1);
        }
        return normalized;
    }
}
